void siftDown(std::vector<int>& a, int root, int end) {
    while (2 * root + 1 <= end) {
        int left = 2 * root + 1, right = left + 1, largest = root;
        if (a[left] > a[largest]) largest = left;
        if (right <= end && a[right] > a[largest]) largest = right;
        if (largest == root) return;
        std::swap(a[root], a[largest]);
        root = largest;
    }
}

void heapSort(std::vector<int>& a) {
    int n = a.size();
    // Bottom-up build is O(n), unlike n separate insertions.
    for (int i = n / 2 - 1; i >= 0; i--) siftDown(a, i, n - 1);
    for (int end = n - 1; end > 0; end--) {
        std::swap(a[0], a[end]);       // largest value to its final slot
        siftDown(a, 0, end - 1);
    }
}

